const raw = $('Webhook').first().json.body || $('Webhook').first().json;
let args;
if (raw.arguments !== undefined) {
  args = typeof raw.arguments === 'string' ? JSON.parse(raw.arguments) : raw.arguments;
} else {
  args = raw;
}

const eventId = args.event_id;
const empleado = args.empleado || '';

// Calendarios por empleado (búsqueda por nombre)
